CREATE OR REPLACE FUNCTION public.sync_agent_tasks_with_sourcing_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status <> 'pending' THEN UPDATE public.agent_tasks t SET status = 'failed', error_code = CASE WHEN NEW.status = 'rejected' THEN 'SOURCING_REQUEST_REJECTED' ELSE 'SOURCING_REQUEST_CLOSED' END, locked_at = NULL, completed_at = now(), updated_at = now() WHERE t.task_type IN ('sourcing_intake','supplier_discovery','quote_comparison') AND t.input_payload->>'sourcing_request_id' = NEW.id::text AND t.status IN ('queued','running','waiting_approval'); INSERT INTO public.agent_events(task_id,event_type,actor_type,payload) SELECT t.id, 'task_rejected', 'system', jsonb_build_object('reason', CASE WHEN NEW.status = 'rejected' THEN 'SOURCING_REQUEST_REJECTED' ELSE 'SOURCING_REQUEST_CLOSED' END, 'request_status', NEW.status) FROM public.agent_tasks t WHERE t.task_type IN ('sourcing_intake','supplier_discovery','quote_comparison') AND t.input_payload->>'sourcing_request_id' = NEW.id::text AND t.status = 'failed' AND t.error_code IN ('SOURCING_REQUEST_REJECTED','SOURCING_REQUEST_CLOSED') AND NOT EXISTS (SELECT 1 FROM public.agent_events e WHERE e.task_id = t.id AND e.event_type = 'task_rejected' AND e.payload->>'request_status' = NEW.status); END IF; RETURN NEW; END; $$; DROP TRIGGER IF EXISTS trg_sync_agent_tasks_with_sourcing_status ON public.sourcing_requests; CREATE TRIGGER trg_sync_agent_tasks_with_sourcing_status AFTER UPDATE OF status ON public.sourcing_requests FOR EACH ROW EXECUTE FUNCTION public.sync_agent_tasks_with_sourcing_status(); REVOKE ALL ON FUNCTION public.sync_agent_tasks_with_sourcing_status() FROM PUBLIC, anon, authenticated;
